  uint32_t bit=((lfsr>>0)^(lfsr>>2)^(lfsr>>3)^(lfsr>>5))&1u;
  lfsr=(lfsr>>1)|(bit<<15);
  uint32_t idx=(lfsr^acc)&15u;
  acc=(acc+sbox[idx]+lfsr)&0xFFFFu;
 }
 printf("%u %u\n",(unsigned)acc,(unsigned)lfsr);
 return 0;
}

